INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1051, '勇', 'yǒng', '勇士', 'yǒng shì', 'นักรบผู้กล้า', '他从来不怕困难，是真正的勇士。', 'เขาไม่เคยกลัวความยากลำบาก เป็นนักรบผู้กล้าอย่างแท้จริง', 'tā cóng lái bú pà kùn nán, shì zhēn zhèng de yǒng shì'),
(1052, '敢', 'gǎn', '勇敢', 'yǒng gǎn', 'กล้าหาญ', '士兵们勇敢地向城门发起了进攻。', 'เหล่าทหารบุกโจมตีประตูเมืองอย่างกล้าหาญ', 'shì bīng men yǒng gǎn de xiàng chéng mén fā qǐ le jìn gōng'),
(1053, '荡', 'dàng', '荡秋千', 'dàng qiū qiān', 'เล่นชิงช้า', '妹妹最喜欢在大树下荡秋千。', 'น้องสาวชอบเล่นชิงช้าใต้ต้นไม้ใหญ่ที่สุด', 'mèi mei zuì xǐ huān zài dà shù xià dàng qiū qiān'),
(1054, '滚', 'gǔn', '翻滚', 'fān gǔn', 'กลิ้ง/หมุนกลิ้ง', '衣服在洗衣机里上下翻滚。', 'เสื้อผ้าหมุนกลิ้งขึ้นลงอยู่ในเครื่องซักผ้า', 'yī fú zài xǐ yī jī lǐ shàng xià fān gǔn'),
(1055, '涌', 'yǒng', '涌出', 'yǒng chū', 'พุ่งออกมา/ไหลทะลัก', '石井里的水在不断地涌出来。', 'น้ำในบ่อหินพุ่งไหลออกมาไม่หยุด', 'shí jǐng lǐ de shuǐ zài bú duàn de yǒng chū lái'),
(1056, '跃', 'yuè', '跳跃', 'tiào yuè', 'กระโดดโลดเต้น', '小鹿总是开心地在树林间跳跃。', 'กวางน้อยกระโดดโลดเต้นอย่างมีความสุขในป่าอยู่เสมอ', 'xiǎo lù zǒng shì kāi xīn de zài shù lín jiān tiào yuè'),
(1057, '借', 'jiè', '借给', 'jiè gěi', 'ให้ยืม', '这本书是我的好朋友借给我的。', 'หนังสือเล่มนี้เพื่อนสนิทให้ฉันยืมมา', 'zhè běn shū shì wǒ de hǎo péng yǒu jiè gěi wǒ de'),
(1058, '尺', 'chǐ', '尺子', 'chǐ zi', 'ไม้บรรทัด', '我在文具店里买了一把尺子。', 'ฉันซื้อไม้บรรทัดหนึ่งอันที่ร้านเครื่องเขียน', 'wǒ zài wén jù diàn lǐ mǎi le yì bǎ chǐ zi'),
(1059, '稠', 'chóu', '稠密', 'chóu mì', 'หนาแน่น', '这个城市虽然不大，但人口稠密。', 'เมืองนี้แม้ไม่ใหญ่ แต่ประชากรหนาแน่น', 'zhè ge chéng shì suī rán bú dà, dàn rén kǒu chóu mì'),
(1060, '啊', 'ā', '啊呀', 'ā yā', 'โอ๊ะ/อุ๊ย (คำอุทาน)', '啊呀，真不巧，一分钟前他刚走了。', 'โอ๊ะ ไม่ทันพอดีเลย เมื่อกี้เขาเพิ่งไปหนึ่งนาที', 'ā yā, zhēn bù qiǎo, yì fēn zhōng qián tā gāng zǒu le'),
(1061, '解', 'jiě', '解开', 'jiě kāi', 'คลาย/แก้ (ปม)', '心理医生慢慢解开了病人的心结。', 'จิตแพทย์ค่อยๆ คลายปมในใจของคนไข้', 'xīn lǐ yī shēng màn màn jiě kāi le bìng rén de xīn jié'),
(1062, '杆', 'gān', '电线杆', 'diàn xiàn gān', 'เสาไฟฟ้า', '一只小鸟落在路旁的电线杆上。', 'นกน้อยตัวหนึ่งเกาะอยู่บนเสาไฟฟ้าข้างถนน', 'yì zhī xiǎo niǎo luò zài lù páng de diàn xiàn gān shàng'),
(1063, '蹦', 'bèng', '蹦跳', 'bèng tiào', 'กระโดดโลดเต้น', '几个小伙伴一路蹦跳着下了山。', 'เพื่อนๆ หลายคนกระโดดโลดเต้นลงเขาไปตลอดทาง', 'jǐ gè xiǎo huǒ bàn yí lù bèng tiào zhe xià le shān'),
(1064, '闹', 'nào', '热闹', 'rè nào', 'คึกคัก/ครึกครื้น', '过节了，市场上人山人海，真热闹。', 'ถึงเทศกาลแล้ว ในตลาดผู้คนล้นหลาม คึกคักจริงๆ', 'guò jié le, shì chǎng shàng rén shān rén hǎi, zhēn rè nào'),
(1065, '宁', 'níng', '安宁', 'ān níng', 'สงบสุข', '人们都希望有安宁幸福的生活。', 'ผู้คนต่างหวังจะมีชีวิตที่สงบสุขและมีความสุข', 'rén men dōu xī wàng yǒu ān níng xìng fú de shēng huó'),
(1066, '靠', 'kào', '依靠', 'yī kào', 'พึ่งพา', '父母老了，儿女就是他们的依靠。', 'เมื่อพ่อแม่แก่ตัวลง ลูกๆ ก็คือที่พึ่งของพวกท่าน', 'fù mǔ lǎo le, ér nǚ jiù shì tā men de yī kào'),
(1067, '与', 'yǔ', '我与他', 'wǒ yǔ tā', 'ฉันกับเขา', '我与他是情同手足的好朋友。', 'ฉันกับเขาเป็นเพื่อนสนิทที่รักกันดั่งพี่น้อง', 'wǒ yǔ tā shì qíng tóng shǒu zú de hǎo péng yǒu'),
(1068, '提', 'tí', '提东西', 'tí dōng xī', 'หิ้วของ', '我长大了，可以帮妈妈提东西了。', 'ฉันโตแล้ว ช่วยแม่หิ้วของได้แล้ว', 'wǒ zhǎng dà le, kě yǐ bāng mā mā tí dōng xī le'),
(1069, '嘻', 'xī', '笑嘻嘻', 'xiào xī xī', 'ยิ้มแฉ่ง/หัวเราะร่า', '他笑嘻嘻的，一定是有什么喜事。', 'เขายิ้มแฉ่ง ต้องมีเรื่องดีๆ แน่ๆ', 'tā xiào xī xī de, yí dìng shì yǒu shén me xǐ shì'),
(1070, '优', 'yōu', '优秀', 'yōu xiù', 'ยอดเยี่ยม', '姐姐是班里数一数二的优秀学生。', 'พี่สาวเป็นนักเรียนยอดเยี่ยมอันดับต้นๆ ของห้อง', 'jiě jie shì bān lǐ shǔ yī shǔ èr de yōu xiù xué shēng'),
(1071, '砖', 'zhuān', '砖头', 'zhuān tóu', 'ก้อนอิฐ', '小小的砖头可以盖起高高的大楼。', 'ก้อนอิฐเล็กๆ สามารถก่อเป็นตึกสูงได้', 'xiǎo xiǎo de zhuān tóu kě yǐ gài qǐ gāo gāo de dà lóu'),
(1072, '辉', 'huī', '光辉', 'guāng huī', 'รัศมี/แสงเรืองรอง', '英雄的光辉形象永远在我们心中。', 'ภาพลักษณ์อันเรืองรองของวีรบุรุษอยู่ในใจเราตลอดไป', 'yīng xióng de guāng huī xíng xiàng yǒng yuǎn zài wǒ men xīn zhōng'),
(1073, '煌', 'huáng', '辉煌', 'huī huáng', 'รุ่งโรจน์/อลังการ', '好一座雄伟壮观、金碧辉煌的宫殿！', 'ช่างเป็นพระราชวังที่ยิ่งใหญ่ตระการตาและอลังการเสียจริง!', 'hǎo yí zuò xióng wěi zhuàng guān, jīn bì huī huáng de gōng diàn'),
(1074, '瓦', 'wǎ', '瓦片', 'wǎ piàn', 'กระเบื้องมุงหลังคา', '屋顶的瓦片排列得整整齐齐。', 'กระเบื้องบนหลังคาเรียงตัวเป็นระเบียบเรียบร้อย', 'wū dǐng de wǎ piàn pái liè de zhěng zhěng qí qí'),
(1075, '琴', 'qín', '古琴', 'gǔ qín', 'กู่ฉิน (พิณจีนโบราณ)', '这位姑娘的古琴弹得真好听！', 'กู่ฉินที่หญิงสาวคนนี้ดีดไพเราะจริงๆ!', 'zhè wèi gū niang de gǔ qín tán de zhēn hǎo tīng'),
(1076, '示', 'shì', '展示', 'zhǎn shì', 'จัดแสดง/นำเสนอ', '展台上展示着不同历史时期的文物。', 'บนแท่นจัดแสดงโบราณวัตถุจากยุคประวัติศาสตร์ต่างๆ', 'zhǎn tái shàng zhǎn shì zhe bù tóng lì shǐ shí qī de wén wù'),
(1077, '周', 'zhōu', '周围', 'zhōu wéi', 'รอบๆ/บริเวณโดยรอบ', '这个房子周围是一片绿油油的稻田。', 'รอบๆ บ้านหลังนี้เป็นทุ่งนาเขียวขจี', 'zhè ge fáng zi zhōu wéi shì yí piàn lǜ yóu yóu de dào tián'),
(1078, '份', 'fèn', '一份', 'yí fèn', 'หนึ่งส่วน/หนึ่งชุด', '你一份，我一份，人人都有份。', 'เธอส่วนหนึ่ง ฉันส่วนหนึ่ง ทุกคนมีส่วนหมด', 'nǐ yí fèn, wǒ yí fèn, rén rén dōu yǒu fèn'),
(1079, '您', 'nín', '您好', 'nín hǎo', 'สวัสดี (สุภาพ)', '见到叔叔阿姨应该主动说您好。', 'เจอคุณลุงคุณป้าควรทักทายว่าสวัสดีก่อน', 'jiàn dào shū shu ā yí yīng gāi zhǔ dòng shuō nín hǎo'),
(1080, '显', 'xiǎn', '明显', 'míng xiǎn', 'ชัดเจน', '近年来，家乡发生了明显的变化。', 'ในช่วงไม่กี่ปีมานี้ บ้านเกิดเปลี่ยนแปลงไปอย่างเห็นได้ชัด', 'jìn nián lái, jiā xiāng fā shēng le míng xiǎn de biàn huà'),
(1081, '躲', 'duǒ', '躲猫猫', 'duǒ māo māo', 'ซ่อนหา (โมโม่)', '几个小伙伴在院子里玩躲猫猫。', 'เพื่อนๆ หลายคนเล่นซ่อนหากันอยู่ในลานบ้าน', 'jǐ gè xiǎo huǒ bàn zài yuàn zi lǐ wán duǒ māo māo'),
(1082, '艳', 'yàn', '艳丽', 'yàn lì', 'ฉูดฉาดสดใส', '妈妈喜欢穿颜色艳丽的衣服。', 'แม่ชอบใส่เสื้อผ้าสีสันฉูดฉาดสดใส', 'mā mā xǐ huān chuān yán sè yàn lì de yī fú'),
(1083, '巧', 'qiǎo', '手巧', 'shǒu qiǎo', 'มือเก่ง/ฝีมือดี', '她不但学习认真，而且心灵手巧。', 'เธอไม่เพียงตั้งใจเรียน แต่ยังหัวไวมือเก่งอีกด้วย', 'tā bú dàn xué xí rèn zhēn, ér qiě xīn líng shǒu qiǎo'),
(1084, '摸', 'mō', '抚摸', 'fǔ mō', 'ลูบไล้/สัมผัส', '妈妈轻轻地抚摸着孩子的头。', 'แม่ลูบศีรษะลูกอย่างแผ่วเบา', 'mā mā qīng qīng de fǔ mō zhe hái zi de tóu'),
(1085, '隔', 'gé', '隔音', 'gé yīn', 'กันเสียง', '这个房子隔音很好，屋里很安静。', 'บ้านหลังนี้กันเสียงได้ดี ในห้องเงียบมาก', 'zhè ge fáng zi gé yīn hěn hǎo, wū lǐ hěn ān jìng'),
(1086, '薄', 'bó', '薄冰', 'bó bīng', 'น้ำแข็งบางๆ', '一场冬雨后，地面上出现了一层薄冰。', 'หลังฝนหนาวตกครั้งหนึ่ง พื้นดินเกิดน้ำแข็งบางๆ ชั้นหนึ่ง', 'yì chǎng dōng yǔ hòu, dì miàn shàng chū xiàn le yì céng bó bīng'),
(1087, '秤', 'chèng', '秤盘', 'chèng pán', 'จานตาชั่ง', '天平两边有两个放东西的秤盘。', 'ตาชั่งสองข้างมีจานสำหรับวางของสองจาน', 'tiān píng liǎng biān yǒu liǎng gè fàng dōng xi de chèng pán'),
(1088, '刘', 'liú', '姓刘', 'xìng liú', 'แซ่หลิว', '我的朋友当中，姓刘的人非常多。', 'ในบรรดาเพื่อนของฉัน คนแซ่หลิวมีเยอะมาก', 'wǒ de péng yǒu dāng zhōng, xìng liú de rén fēi cháng duō'),
(1089, '华', 'huá', '中华', 'zhōng huá', 'จงหัว (จีน)', '我为自己是中华儿女感到骄傲。', 'ฉันภูมิใจที่ตัวเองเป็นลูกหลานชาวจีน', 'wǒ wèi zì jǐ shì zhōng huá ér nǚ gǎn dào jiāo ào'),
(1090, '吴', 'wú', '吴老师', 'wú lǎo shī', 'ครูอู๋ (แซ่อู๋)', '吴老师的名字我一下子就记住了。', 'ชื่อของครูอู๋ฉันจำได้ในทันที', 'wú lǎo shī de míng zi wǒ yí xià zi jiù jì zhù le'),
(1091, '迟', 'chí', '迟到', 'chí dào', 'มาสาย', '她早睡早起，上学从来不迟到。', 'เธอนอนเร็วตื่นเช้า ไปโรงเรียนไม่เคยสาย', 'tā zǎo shuì zǎo qǐ, shàng xué cóng lái bù chí dào'),
(1092, '怦', 'pēng', '怦怦跳', 'pēng pēng tiào', '(ใจ)เต้นตึกๆ', '王子一见到公主，心里怦怦跳。', 'พอเจ้าชายเห็นเจ้าหญิง หัวใจก็เต้นตึกๆ', 'wáng zǐ yí jiàn dào gōng zhǔ, xīn lǐ pēng pēng tiào'),
(1093, '鼓', 'gǔ', '鼓手', 'gǔ shǒu', 'มือกลอง', '他希望以后成为一名优秀的鼓手。', 'เขาหวังว่าอนาคตจะเป็นมือกลองที่ยอดเยี่ยม', 'tā xī wàng yǐ hòu chéng wéi yì míng yōu xiù de gǔ shǒu'),
(1094, '尽', 'jìn', '尽头', 'jìn tóu', 'สุดปลาย/ปลายทาง', '在小路的尽头有一座小洋房。', 'ที่สุดปลายทางเดินเล็กๆ มีบ้านสไตล์ตะวันตกหลังเล็กอยู่หลังหนึ่ง', 'zài xiǎo lù de jìn tóu yǒu yí zuò xiǎo yáng fáng'),
(1095, '牵', 'qiān', '牵着', 'qiān zhe', 'จูง', '放牛娃牵着牛走在乡间小路上。', 'เด็กเลี้ยงวัวจูงวัวเดินอยู่บนทางเดินเล็กๆ ในชนบท', 'fàng niú wá qiān zhe niú zǒu zài xiāng jiān xiǎo lù shàng'),
(1096, '弄', 'nòng', '捉弄', 'zhuō nòng', 'แกล้ง/ล้อเล่น', '他被人捉弄了，非常生气。', 'เขาถูกคนแกล้ง โกรธมาก', 'tā bèi rén zhuō nòng le, fēi cháng shēng qì'),
(1097, '挂', 'guà', '挂起来', 'guà qǐ lái', 'แขวนขึ้น', '来，我帮你把大衣挂起来吧。', 'มาสิ ฉันช่วยเธอเอาเสื้อโค้ทแขวนขึ้นนะ', 'lái, wǒ bāng nǐ bǎ dà yī guà qǐ lái ba'),
(1098, '便', 'biàn', '方便', 'fāng biàn', 'สะดวก', '我家离公交车站不远，非常方便。', 'บ้านฉันอยู่ไม่ไกลจากป้ายรถเมล์ สะดวกมาก', 'wǒ jiā lí gōng jiāo chē zhàn bù yuǎn, fēi cháng fāng biàn'),
(1099, '盼', 'pàn', '盼望', 'pàn wàng', 'เฝ้ารอ/ตั้งตารอ', '盼望着，盼望着，春天的脚步近了。', 'เฝ้ารอ เฝ้ารอ ย่างก้าวของฤดูใบไม้ผลิใกล้เข้ามาแล้ว', 'pàn wàng zhe, pàn wàng zhe, chūn tiān de jiǎo bù jìn le'),
(1100, '曲', 'qǔ', '乐曲', 'yuè qǔ', 'บทเพลง/ทำนอง', '我的耳边响起了一阵轻快的乐曲。', 'ข้างหูฉันดังขึ้นด้วยทำนองเพลงที่สนุกสดใส', 'wǒ de ěr biān xiǎng qǐ le yí zhèn qīng kuài de yuè qǔ');
